   339	\begin{lemma}[Formalization support for Lemma~\ref{lem:povm-to-obs}]
   340		\label{lem:povm-to-obs-operator-families}
   341		\lean{MIPStarRE.QPBT.povm_to_obs}
   342		\leanok
   343		\uses{def:approx-question-indexed-operators, def:povm-distance}
   344		This formalization-only auxiliary is not a named statement of the paper; it
   345		isolates the finite-sum estimate used in Lemma~\ref{lem:povm-to-obs}. Let
   346		$\{A^x_a\}$ and $\{B^x_a\}$ be arbitrary operator families and let
   347		$|\alpha_a|=1$. Then
   348		\[
   349			\E_x \Big\|\sum_a \alpha_a(A^x_a-B^x_a)\ket\psi\Big\|^2
   350			\leq |\mathcal A|\,\E_x\sum_a
   351			\big\|(A^x_a-B^x_a)\ket\psi\big\|^2.
   352		\]
   353	\end{lemma}
   354	\begin{proof}
   355		\leanok
   356		Apply the triangle inequality to the sum over $a$, square, and use the
   357		finite Cauchy--Schwarz inequality. Averaging preserves the resulting
   358		pointwise inequality.
